def localize_poi_item(p: dict, lang: str = "en") -> dict:
    """Returns a copy of POI dict `p` with fields localized for `lang` ('en' default or 'vi')."""
    item = dict(p)
    pid = item.get("id", "")
    reg = item.get("region", "")

    if pid in _POI_EN_BY_ID:
        name_en_ascii, name_en_disp, desc_en = _POI_EN_BY_ID[pid]
    elif pid.startswith("enex_"):
        m = re.match(r"^enex_([a-z0-9_]+)_\d+$", pid)
        code = m.group(1).upper() if m else ""
        if code in _ENEX_EN_RULES:
            base_ascii, base_disp, desc_en = _ENEX_EN_RULES[code]
            name_en_ascii = f"{base_ascii} ({reg})"[:44]
            name_en_disp = f"{base_disp} — {reg}"
        else:
            name_en_ascii = item.get("name", "")
            name_en_disp = item.get("name_vi", name_en_ascii)
            desc_en = item.get("desc", "")
    else:
        name_en_ascii = item.get("name", "")
        name_en_disp = item.get("name_vi", name_en_ascii)
        desc_en = item.get("desc", "")

    name_vi_ascii = item.get("name", "")
    name_vi_disp = item.get("name_vi", name_vi_ascii)
    desc_vi = item.get("desc", "")

    item["name_en"] = name_en_ascii
    item["name_en_display"] = name_en_disp
    item["desc_en"] = desc_en
    item["name_vi_ascii"] = name_vi_ascii
    item["name_vi_orig"] = name_vi_disp
    item["desc_vi"] = desc_vi

    if lang == "vi":
        item["name"] = name_vi_ascii
        item["name_vi"] = name_vi_disp
        item["desc"] = desc_vi
    else:
        item["name"] = name_en_ascii
        item["name_vi"] = name_en_disp
        item["desc"] = desc_en
    return item


def compute_compass_dir(dx: float, dy: float, lang: str = "en") -> str:
    """Computes compass direction (N, NE, E, SE, S, SW, W, NW) from player to destination."""
    is_vi = (lang == "vi")
    if abs(dx) < 1.0 and abs(dy) < 1.0:
        return "TAI CHO" if is_vi else "HERE"
    ang = (math.degrees(math.atan2(dx, dy)) + 360.0) % 360.0
    dirs = (
        ["BAC", "DONG-BAC", "DONG", "DONG-NAM", "NAM", "TAY-NAM", "TAY", "TAY-BAC"]
        if is_vi
        else ["N", "NE", "E", "SE", "S", "SW", "W", "NW"]
    )
    idx = int(((ang + 22.5) % 360.0) // 45.0)
    return dirs[idx]


def format_distance(dist_m: float) -> str:
    """Formats distance in m or km."""
    if dist_m >= 1000.0:
        return f"{dist_m / 1000.0:.2f}km"
    return f"{int(round(dist_m))}m"


def get_pois_for_category(cat_code: str, player_pos: tuple = (2495.0, -1687.0, 13.5), lang: str = "en") -> list[dict]:
    """
    Returns POIs in `cat_code` sorted nearest-first from `player_pos`, localized in `lang` ('en' default or 'vi').
    """
    px, py, _pz = player_pos
    results = []
    for p in CURATED_GG_MAP_POIS:
        if cat_code != "ALL" and p["cat"] != cat_code:
            continue
        dx = float(p["x"]) - float(px)
        dy = float(p["y"]) - float(py)
        dist_2d = math.hypot(dx, dy)
        item = localize_poi_item(p, lang=lang)
        item["dist_m"] = round(dist_2d, 1)
        item["dist_str"] = format_distance(dist_2d)
        item["compass"] = compute_compass_dir(dx, dy, lang=lang)
        results.append(item)

    results.sort(key=lambda item: item["dist_m"])
    return results
